const stored = $getWorkflowStaticData("global").ingredients;
const incoming = $input.first().json;
const staticData = $getWorkflowStaticData("global");
const today = new Date().toISOString().split("T")[0];

staticData.genCounter ??= {};
staticData.genCounter[today] ??= 0;
staticData.genCounter[today]++;

return [
  {
    json: {
      ...stored[0],
      ...incoming,
      today,
      count: staticData.genCounter[today],
    },
  },
];

let raw = $input.first().json.output;

// remove code fences
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();

// parse safely
const data = JSON.parse(raw);

return [{ json: data }];
